-- Migration 006: pharmacist operations
--   * supplier_orders: one-click restock from a (simulated) wholesale supplier
--   * orders.is_sample: orders generated by the demo simulator, not real customers
--   * pharmacies.last_sim_at: when the simulator last generated sample orders

CREATE TABLE IF NOT EXISTS supplier_orders (
  id            SERIAL PRIMARY KEY,
  pharmacy_id   INT           NOT NULL REFERENCES pharmacies(id) ON DELETE CASCADE,
  medicine_id   INT           NOT NULL REFERENCES medicines(id)  ON DELETE CASCADE,
  supplier      TEXT          NOT NULL,
  quantity      INT           NOT NULL CHECK (quantity > 0),
  unit_cost     NUMERIC(10,2) NOT NULL,
  status        TEXT          NOT NULL DEFAULT 'ordered' CHECK (status IN ('ordered', 'delivered')),
  created_at    TIMESTAMPTZ   NOT NULL DEFAULT now(),
  delivered_at  TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS supplier_orders_pharmacy_idx ON supplier_orders(pharmacy_id, created_at DESC);

ALTER TABLE orders     ADD COLUMN IF NOT EXISTS is_sample   BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE pharmacies ADD COLUMN IF NOT EXISTS last_sim_at TIMESTAMPTZ;
CREATE INDEX IF NOT EXISTS orders_pharmacy_idx ON orders(pharmacy_id, created_at DESC);
